"""Returns a customized name of a rule. When the prefix matches a key
       from 'prefix_dict', the prefix will be replaced with the
       'prefix_dict[key]' value.

    Args:
        prefix_dict: the dictionary of library name prefixes.
        name: rule name.
    Returns:
        customized name when the prefix is replaces with a value from
        'prefix_dict'.
    """
def _llvm_get_rule_name(prefix_dict: Any, name: Any) -> object {
    concat_format = "%s%s";
    for (old_prefix, new_prefix) in prefix_dict.items() {
        if name.startswith(old_prefix) {
            return (concat_format % (new_prefix, name[(len(old_prefix) + 1):]));
        }
    }
    return name;
}

"""Pex does not like the header Pants adds to lockfiles, as it violates JSON.

    Note that we only strip lines starting with `//`, which is all that Pants will ever add. If
    users add their own comments, things will fail.
    """
def _strip_comments_from_pex_json_lockfile(lockfile_bytes: bytes) -> bytes {
    return b'\n'.join(
        line
        for line in lockfile_bytes.splitlines()
        if not line.lstrip().startswith(b'//')
    );
}

